import { useTranslation } from 'react-i18next';
import { reportApi } from '../../api/services';
import { Button } from '../../components/ui';
import { FileSpreadsheet, FileText, Download } from 'lucide-react';
import { toastSuccess, toastError } from '../../utils/errorHandler';
import { downloadBlob, getFileExtension } from '../../utils/download';

export default function ReportsPage() {
  const { t } = useTranslation();

  const handleExport = async (format) => {
    try {
      const { data } = await reportApi.exportEmployees(format);
      downloadBlob(data, `employees_report.${getFileExtension(format)}`);
      toastSuccess(t('report.downloadSuccess'));
    } catch (err) {
      toastError(err);
    }
  };

  const upcomingReports = [
    t('report.assetUtilization'),
    t('report.docExpiry'),
    t('report.headcountByDept'),
    t('report.joiningTrend'),
  ];

  return (
    <div className="space-y-6 max-w-2xl">
      <div className="bg-white rounded-xl border border-slate-200 p-6">
        <h2 className="text-base font-semibold text-slate-800 mb-1">{t('report.employeeReports')}</h2>
        <p className="text-sm text-slate-500 mb-5">{t('report.exportDescription')}</p>
        <div className="flex flex-wrap gap-3">
          <Button onClick={() => handleExport('excel')}>
            <FileSpreadsheet size={16} /> {t('report.exportExcel')}
          </Button>
          <Button variant="secondary" onClick={() => handleExport('csv')}>
            <Download size={16} /> {t('report.exportCsv')}
          </Button>
          <Button variant="secondary" onClick={() => handleExport('pdf')}>
            <FileText size={16} /> {t('report.exportPdf')}
          </Button>
        </div>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 p-6">
        <h2 className="text-base font-semibold text-slate-800 mb-1">{t('report.moreReports')}</h2>
        <p className="text-sm text-slate-500">{t('report.moreReportsSubtitle')}</p>
        <ul className="mt-4 space-y-2">
          {upcomingReports.map((r) => (
            <li key={r} className="flex items-center gap-2 text-sm text-slate-400">
              <span className="w-1.5 h-1.5 bg-slate-300 rounded-full" />
              {r}
              <span className="text-xs bg-slate-100 px-2 py-0.5 rounded-full">{t('common.comingSoon')}</span>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}
